import { temporaryDirectory } from "../temporary-directories.ts";
import type { ChildProcessByStdio } from "node:child_process";
import type { Readable } from "node:stream";
import type { AddressInfo } from "node:net";
interface ToolOutput {
  call_id: string;
  type: string;
  output: string | { text: string }[];
}
import { spawn } from "node:child_process";
import { once } from "node:events";
import { rm } from "node:fs/promises";
import { createServer } from "node:http";
import { createRequire } from "node:module";
import path from "node:path";

function responseEvents(id: string, item: unknown) {
  return [
    { type: "response.created", response: { id } },
    { type: "response.output_item.done", item },
    {
      type: "response.completed",
      response: {
        id,
        usage: {
          input_tokens: 0,
          input_tokens_details: null,
          output_tokens: 0,
          output_tokens_details: null,
          total_tokens: 0,
        },
      },
    },
  ]
    .map((event) => `event: ${event.type}\ndata: ${JSON.stringify(event)}\n\n`)
    .join("");
}

/** Execute one scripted cell through the real CLI, external code host, and MCP. */
export async function runControlledCodeMode({
  code,
  mcpServer,
  workingDirectory,
  prompt,
}: {
  code: string;
  mcpServer: { command: string; args: string[] };
  workingDirectory: string;
  prompt: string;
}) {
  // Resolve through the SDK so the launcher and native host use its pinned version.
  const sdkRequire = createRequire(import.meta.resolve("@openai/codex-sdk"));
  const launcher = path.join(
    path.dirname(sdkRequire.resolve("@openai/codex/package.json")),
    "bin",
    "codex.js",
  );
  const codexHome = await temporaryDirectory("codex-controlled-ipc-");
  const toolOutputs = new Map<string, ToolOutput>();
  const serverErrors: string[] = [];
  let responseCount = 0;
  let pendingCallId = "controlled-exec";
  let child: ChildProcessByStdio<null, null, Readable> | undefined;
  let closed: Promise<number | null> | undefined;
  let stderr = "";
  const server = createServer(async (request, response) => {
    try {
      // The CLI also sends analytics here; those must not advance the model script.
      if (request.url !== "/v1/responses") {
        request.resume();
        response.writeHead(200, { "content-type": "application/json" });
        response.end("{}");
        return;
      }
      const chunks = await request.toArray();
      const body = JSON.parse(Buffer.concat(chunks).toString("utf8"));
      for (const item of body.input ?? []) {
        if (
          item.type === "custom_tool_call_output" ||
          item.type === "function_call_output"
        ) {
          toolOutputs.set(item.call_id, item);
        }
      }
      responseCount += 1;
      const id = `controlled-response-${responseCount}`;
      const output = toolOutputs.get(pendingCallId)?.output;
      const status = typeof output === "string" ? output : output?.[0]?.text;
      const runningCell = status?.match(/^Script running with cell ID (\d+)\n/);
      if (runningCell) pendingCallId = `controlled-wait-${responseCount}`;
      const item =
        responseCount === 1
          ? {
              type: "custom_tool_call",
              call_id: pendingCallId,
              name: "exec",
              input: code,
            }
          : runningCell
            ? {
                type: "function_call",
                call_id: pendingCallId,
                name: "wait",
                arguments: JSON.stringify({ cell_id: runningCell[1] }),
              }
            : {
                type: "message",
                id: `controlled-message-${responseCount}`,
                role: "assistant",
                content: [{ type: "output_text", text: "Eval complete." }],
              };
      response.writeHead(200, { "content-type": "text/event-stream" });
      response.end(responseEvents(id, item));
    } catch (error) {
      serverErrors.push(String(error));
      response.writeHead(500);
      response.end("Controlled provider failed.");
    }
  });
  try {
    await new Promise<void>((resolve, reject) => {
      server.once("error", reject);
      server.listen(0, "127.0.0.1", resolve);
    });
    const port = (server.address() as AddressInfo).port;
    const config = [
      'model_provider="controlled"',
      `model_providers.controlled={name="controlled",base_url="http://127.0.0.1:${port}/v1",wire_api="responses",requires_openai_auth=false,supports_websockets=false}`,
      "features.code_mode.enabled=true",
      "features.code_mode_host.enabled=true",
      "features.code_mode_host.disable_in_process_fallback=true",
      `mcp_servers.cs_artifacts.command=${JSON.stringify(mcpServer.command)}`,
      `mcp_servers.cs_artifacts.args=${JSON.stringify(mcpServer.args)}`,
    ];
    // Pass only process-launch essentials; never inherit the caller's model auth.
    const env: NodeJS.ProcessEnv = {
      CODEX_HOME: codexHome,
      CODEX_SQLITE_HOME: codexHome,
    };
    for (const key of [
      "PATH",
      "SystemRoot",
      "SystemDrive",
      "ComSpec",
      "PATHEXT",
      "TEMP",
      "TMP",
      "TMPDIR",
    ]) {
      if (process.env[key] !== undefined) env[key] = process.env[key];
    }
    const args = [
      launcher,
      "exec",
      "--skip-git-repo-check",
      "--experimental-json",
      "--sandbox",
      "read-only",
      "-m",
      "gpt-5.1-codex",
      ...config.flatMap((entry) => ["-c", entry]),
      prompt,
    ];
    child = spawn(process.execPath, args, {
      cwd: workingDirectory,
      env,
      // JSONL stdout can duplicate the deliberately oversized MCP response.
      stdio: ["ignore", "ignore", "pipe"],
    });
    closed = new Promise((resolve) => child!.once("close", resolve));
    child.stderr.setEncoding("utf8").on("data", (chunk) => {
      stderr += chunk;
    });
    const exitCode: number | null = (await once(child, "close"))[0];
    return {
      exitCode,
      toolOutputs: [...toolOutputs.values()],
      stderr,
      serverErrors,
    };
  } finally {
    child?.kill();
    if (closed) await closed;
    server.closeAllConnections();
    await new Promise((resolve) => server.close(resolve));
    await rm(codexHome, { recursive: true, force: true });
  }
}

import { workerDraft } from "../../scan-draft-fixture.ts";
import { readJson, writeJson } from "../json.ts";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdir, realpath } from "node:fs/promises";
import path from "node:path";
import { sourceReferences } from "../source-references.ts";

// This is the existing code-mode transport ceiling, used only to size the eval.
const IPC_FRAME_LIMIT_BYTES = 64 * 1024 * 1024;
const SCAN_ID = "7fc17317-9594-49e0-b06a-d72fd7e14bba";

/** Generate one reducer assignment; no repository scan or external service runs. */
export async function createReducerPagingFixture(root: string) {
  const fixtureRoot = await realpath(root);
  const scanRoot = path.join(fixtureRoot, "scan");
  const deepRoot = path.join(scanRoot, "artifacts", "deep_discovery");
  const workerRoot = path.join(deepRoot, "workers", "discovery-0001", "output");
  const previousRoot = path.join(deepRoot, "dedup", "dedup-0001", "output");
  const outputRoot = path.join(deepRoot, "dedup", "dedup-0002", "output");
  await Promise.all(
    [workerRoot, previousRoot, outputRoot].map((directory) =>
      mkdir(directory, { recursive: true }),
    ),
  );

  const freshHtml = finding("reflected-html", {
    title: "Request text reaches an HTML response without encoding",
    summary: paddedSummary(IPC_FRAME_LIMIT_BYTES / 2),
    remediation: "HTML-encode request text at the response rendering boundary.",
  });
  const freshArchive = finding("archive-path", {
    title: "Archive entry paths escape the extraction directory",
    summary:
      "An independently reachable archive importer joins an untrusted entry path to the extraction directory without checking containment. This is unrelated to HTML rendering or database queries.",
    remediation:
      "Resolve each archive entry against the extraction directory and enforce containment before writing it.",
  });
  const previousOriginal = finding("query-injection", {
    title: "Account lookup interpolates request text into a database query",
    summary:
      "The account lookup builds a query by concatenating request-controlled text. Parameter binding is absent on this path.",
    remediation: "Use parameter binding for account lookup query values.",
  });
  const synthesizedHistory = {
    ...previousOriginal,
    summary:
      "Earlier synthesis also established that the transactional account lookup calls the same unsafe query builder. Both paths need the shared parameter-binding fix.",
  };
  const previousSourceId = "previous-worker:0";
  const previousCanonical = {
    ...previousOriginal,
    summary:
      "Account lookup and transactional lookup share a query builder that interpolates request text. A shared parameter-binding fix covers both reachable paths.",
    provenance: {
      ...previousOriginal.provenance,
      sourceFindingIds: [previousSourceId],
      sourceFindings: [{ id: previousSourceId, finding: previousOriginal }],
      previousFindings: [synthesizedHistory],
    },
  };
  const workerId = "current-worker";
  const currentFindings = [freshHtml, freshArchive];
  const expectedSources = new Map<string, ReturnType<typeof finding>>([
    ...currentFindings.map(
      (value, index) => [`${workerId}:${index}`, value] as const,
    ),
    [previousSourceId, previousOriginal],
  ]);
  const sourceSha256ById = Object.fromEntries(
    [...expectedSources].map(([id, value]) => [id, canonicalSha256(value)]),
  );
  const result = {
    scanId: SCAN_ID,
    findings: currentFindings,
    scope: {
      summary: "Three independent synthetic request-processing issues.",
    },
  };
  const previous = {
    scanId: SCAN_ID,
    findings: [previousCanonical],
    threatModel: {
      summary:
        "Untrusted request inputs cross distinct output, filesystem, and query boundaries.",
    },
  };
  const workerPath = path.join(workerRoot, "result.json");
  const previousPath = path.join(previousRoot, "result.json");
  await writeJson(workerPath, {
    ...result,
    coverage: workerDraft([]).coverage,
  });
  await writeJson(previousPath, previous);

  const logicalInputs = {
    discoveries: [
      {
        workerId,
        result: {
          ...result,
          findings: currentFindings.map(sourceReferences({ id: workerId })),
        },
      },
    ],
    previous,
  };
  const { bytes, stringEscapes } = jsonMetrics(logicalInputs);
  // The old response included JSON.stringify(inputs) as text and inputs again
  // as structuredContent. Count its exact bytes without allocating both copies.
  const envelopeBytes =
    Buffer.byteLength(
      JSON.stringify({
        content: [{ type: "text", text: "" }],
        structuredContent: null,
      }),
    ) - Buffer.byteLength("null");
  const legacyResponseBytes = envelopeBytes + bytes * 2 + stringEscapes;
  assert.ok(legacyResponseBytes > IPC_FRAME_LIMIT_BYTES);
  return {
    context: {
      root: outputRoot,
      repoRoot: fixtureRoot,
      scanId: SCAN_ID,
      layout: "reducer" as const,
      deepReducer: {
        scanRoot,
        claimedWorkers: [{ id: workerId, resultPath: workerPath }],
        previousReducerResultPath: previousPath,
      },
    },
    resultPath: path.join(outputRoot, "result.json"),
    expected: {
      sourceSha256ById,
      sourceIdentityById: Object.fromEntries(
        [...expectedSources].map(([id, value]) => [id, value.identity]),
      ),
      previousSourceId,
      historySha256: canonicalSha256(synthesizedHistory),
    },
    measurements: {
      ipcFrameLimitBytes: IPC_FRAME_LIMIT_BYTES,
      largeSemanticFieldBytes: Buffer.byteLength(freshHtml.summary),
      logicalInputBytes: bytes,
      legacyResponseBytes,
    },
  };
}

/** Fail on lost, duplicated, substituted, or de-identified reducer evidence. */
export async function gradeReducerPagingResult(
  fixture: Awaited<ReturnType<typeof createReducerPagingFixture>>,
) {
  const result = await readJson(fixture.resultPath);
  assert.equal(result.scanId, fixture.context.scanId);
  assert.notEqual(result.complete, false);
  assert.ok(Array.isArray(result.findings));
  const expectedIds = Object.keys(fixture.expected.sourceSha256ById).sort();
  assert.equal(
    result.findings.length,
    expectedIds.length,
    "the three independent issues must remain separate output findings",
  );
  const refs = [];
  for (const finding of result.findings) {
    const provenance = finding.provenance;
    assert.ok(Array.isArray(provenance?.sourceFindingIds));
    assert.equal(
      provenance.sourceFindingIds.length,
      1,
      "each independent output finding must reference only its own source",
    );
    const [sourceId] = provenance.sourceFindingIds;
    assert.deepEqual(
      finding.identity,
      fixture.expected.sourceIdentityById[sourceId],
      `output identity must match its source ${sourceId}`,
    );
    assert.ok(Array.isArray(provenance?.sourceFindings));
    refs.push(...provenance.sourceFindingIds);
    assert.deepEqual(
      provenance.sourceFindings
        .map((source: { id: string }) => source.id)
        .sort(),
      [...provenance.sourceFindingIds].sort(),
      "each output finding must retain exactly its attributed originals",
    );
    const [source] = provenance.sourceFindings;
    assert.equal(
      canonicalSha256(source.finding),
      fixture.expected.sourceSha256ById[source.id],
      `original evidence changed for ${source.id}`,
    );
  }
  assert.deepEqual(
    refs.sort(),
    expectedIds,
    "each assigned reference must occur exactly once",
  );
  const previous = result.findings.find(
    (finding: { provenance: { sourceFindingIds: string[] } }) =>
      finding.provenance.sourceFindingIds.includes(
        fixture.expected.previousSourceId,
      ),
  );
  assert.ok(
    previous.provenance.previousFindings?.some(
      (history: unknown) =>
        canonicalSha256(history) === fixture.expected.historySha256,
    ),
    "the prior synthesized history must survive losslessly",
  );
  return {
    findingCount: result.findings.length,
    accountedSourceCount: refs.length,
    preservedOriginalCount: refs.length,
    previousIdentityPreserved: true,
    synthesizedHistoryPreserved: true,
  };
}

function finding(
  id: "reflected-html" | "archive-path" | "query-injection",
  extra: Record<"title" | "summary" | "remediation", string>,
) {
  return {
    ruleId: "synthetic." + id,
    identity: { anchor: id },
    title: extra.title,
    summary: extra.summary,
    severity: { level: "high" },
    confidence: { level: "high", rationale: "Synthetic validated fixture." },
    taxonomy: {
      category: id,
      cwe: [
        {
          "reflected-html": "CWE-79",
          "archive-path": "CWE-22",
          "query-injection": "CWE-89",
        }[id],
      ],
    },
    locations: [{ path: `src/${id}.ts`, startLine: 1, endLine: 2 }],
    remediation: extra.remediation,
    provenance: { source: "local_plugin" },
  };
}

function paddedSummary(bytes: number) {
  const beginning =
    "BEGIN ISSUE: Request text reaches an HTML response without encoding. The following repeated text is synthetic padding to exercise byte-aware paging, not additional evidence.\n";
  const ending =
    "\nEND ISSUE: The remedy is HTML encoding at the response boundary. Archive extraction and query interpolation are distinct issues requiring independent fixes.";
  const available =
    bytes - Buffer.byteLength(beginning) - Buffer.byteLength(ending);
  const unit = '"\\\n😀';
  const repeats = Math.floor(available / Buffer.byteLength(unit));
  return (
    beginning +
    unit.repeat(repeats) +
    "x".repeat(available % Buffer.byteLength(unit)) +
    ending
  );
}

function canonicalSha256(value: unknown) {
  const hash = createHash("sha256");
  visitJson(value, (chunk) => hash.update(chunk), true);
  return hash.digest("hex");
}

function jsonMetrics(value: unknown) {
  let bytes = 0;
  let stringEscapes = 0;
  visitJson(value, (chunk) => {
    bytes += Buffer.byteLength(chunk);
    for (let index = 0; index < chunk.length; index += 1) {
      if (chunk[index] === '"' || chunk[index] === "\\") stringEscapes += 1;
    }
  });
  return { bytes, stringEscapes };
}

// Hash and measure one scalar at a time instead of retaining another complete
// copy of the oversized document. Fixture values contain only JSON types.
function visitJson(
  value: unknown,
  emit: (chunk: string) => void,
  sorted = false,
) {
  if (Array.isArray(value)) {
    emit("[");
    value.forEach((item, index) => {
      if (index > 0) emit(",");
      visitJson(item, emit, sorted);
    });
    emit("]");
  } else if (value !== null && typeof value === "object") {
    emit("{");
    const keys = Object.keys(value);
    if (sorted) keys.sort();
    keys.forEach((key, index) => {
      if (index > 0) emit(",");
      emit(JSON.stringify(key));
      emit(":");
      visitJson((value as Record<string, unknown>)[key], emit, sorted);
    });
    emit("}");
  } else {
    emit(JSON.stringify(value)!);
  }
}

import { writeJson } from "../json.ts";
import type { DeepReducerPageInput } from "../../../src/artifact-deep-reducer-pages.js";
export interface ReducerTraceEvent {
  event: string;
  id: number;
  tool?: string;
  input?: DeepReducerPageInput;
  bytes?: number;
  injected?: boolean;
  nextCursor?: string;
}
import assert from "node:assert/strict";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { Codex } from "@openai/codex-sdk";
import { build } from "esbuild";
import { importSource } from "../../import-module.ts";
import { runControlledCodeMode } from "./controlled-code-mode.ts";
import {
  createReducerPagingFixture,
  gradeReducerPagingResult,
} from "./deep-reducer-paging-fixture.ts";

interface ReducerPagingEvalOptions {
  root: string;
  mode?: "deterministic" | "model";
  model?: string;
}

/** Run one reducer through real code-mode IPC and the production artifact tools. */
export async function runReducerPagingEval(options: ReducerPagingEvalOptions) {
  try {
    const result = await runReducer(options);
    await writeJson(path.join(options.root, "report.json"), result.report);
    return result;
  } catch (error) {
    await writeJson(path.join(options.root, "report.json"), {
      mode: options.mode ?? "deterministic",
      ...(options.model ? { model: options.model } : {}),
      error: error instanceof Error ? error.stack : String(error),
    }).catch(() => {});
    throw error;
  }
}

async function runReducer({
  root,
  mode = "deterministic",
  model,
}: ReducerPagingEvalOptions) {
  assert.ok(mode === "deterministic" || mode === "model");
  const fixture = await createReducerPagingFixture(root);
  const tracePath = path.join(root, "tool-trace.jsonl");
  const serverConfigPath = path.join(root, "server-config.json");
  const serverPath = path.join(root, "artifact-server.cjs");
  await writeFile(tracePath, "");
  await writeJson(serverConfigPath, { context: fixture.context, tracePath });
  const [, { renderDedupPrompt }] = await Promise.all([
    build({
      entryPoints: [
        path.join(import.meta.dirname, "deep-reducer-paging-server.ts"),
      ],
      outfile: serverPath,
      bundle: true,
      platform: "node",
      format: "cjs",
      loader: { ".md": "text" },
    }),
    importSource(
      path.join(import.meta.dirname, "../../../src/deep-scan/templates.ts"),
      { loader: { ".md": "text" } },
    ),
  ]);
  const claimedWorkerIds = fixture.context.deepReducer.claimedWorkers.map(
    (worker) => worker.id,
  );
  const prompt = renderDedupPrompt("paging-eval", claimedWorkerIds);
  assert.deepEqual(JSON.parse(prompt.match(/```json\n([\s\S]*?)\n```/)[1]), {
    reducerLabel: "paging-eval",
    claimedWorkerIds,
  });
  const mcpServer = {
    command: process.execPath,
    args: [serverPath, serverConfigPath],
    required: true,
  };
  let transport;
  let usage;
  if (mode === "deterministic") {
    transport = await runControlledCodeMode({
      code: controlledReducerCode,
      mcpServer,
      workingDirectory: fixture.context.repoRoot,
      prompt,
    });
    assert.equal(transport.exitCode, 0, transport.stderr);
    assert.deepEqual(transport.serverErrors, []);
    const output = JSON.stringify(transport.toolOutputs);
    assert.match(
      output,
      /code-mode delegate response exceeds the IPC frame limit: code-mode IPC frame length [0-9]+ exceeds 67108864 bytes/,
      "the real transport must reject the legacy payload",
    );
    assert.match(output, /reductionRecorded/);
  } else {
    const codex = new Codex({
      config: {
        mcp_servers: { cs_artifacts: mcpServer },
        features: {
          code_mode: { enabled: true },
          code_mode_host: { enabled: true, disable_in_process_fallback: true },
        },
      },
    });
    const thread = codex.startThread({
      ...(model ? { model } : {}),
      workingDirectory: fixture.context.repoRoot,
      skipGitRepoCheck: true,
      approvalPolicy: "never",
      sandboxMode: "read-only",
    });
    const result = await thread.run(prompt);
    usage = result.usage;
    await writeFile(
      path.join(root, "model-response.txt"),
      result.finalResponse,
    );
  }
  const trace = (await readFile(tracePath, "utf8"))
    .trim()
    .split("\n")
    .filter(Boolean)
    .map((line) => JSON.parse(line));
  const report = {
    mode,
    ...(model ? { model } : {}),
    ...fixture.measurements,
    ...gradeReducerPagingTrace(trace, fixture.measurements.ipcFrameLimitBytes),
    ...(transport ? { realIpcErrorObserved: true } : {}),
    ...(await gradeReducerPagingResult(fixture)),
    ...(usage ? { usage } : {}),
  };
  return { report, fixture };
}

/** Grade the captured I/O independently of model wording or another model run. */
export function gradeReducerPagingTrace(
  trace: ReducerTraceEvent[],
  ipcFrameLimitBytes: number,
) {
  assert.ok(trace.length > 0, "The reducer produced no tool trace.");
  const reads = trace.filter(
    (event) =>
      event.event === "request" &&
      event.tool === "get_codex_security_deep_reducer_inputs",
  );
  const readsById = new Map(reads.map((event) => [event.id, event]));
  const injected = trace.filter((event) => event.injected);
  assert.equal(injected.length, 1);
  assert.ok(injected[0].bytes! > ipcFrameLimitBytes);
  const failed = reads.find((event) => event.id === injected[0].id);
  const retried = reads.find((event) => event.id > failed!.id);
  assert.ok(retried, "the reducer must recover from the oversized response");
  assert.ok(
    retried.input!.maxBytes < failed!.input!.maxBytes,
    "recovery must change the failed request's byte budget",
  );
  assert.equal(retried.input!.cursor ?? "0", failed!.input!.cursor ?? "0");
  assert.equal(retried.input!.findingRef, failed!.input!.findingRef);
  const pages = trace.filter(
    (event) =>
      event.event === "response" && !event.injected && readsById.has(event.id),
  );
  for (const page of pages) {
    const request = readsById.get(page.id);
    assert.ok(page.bytes! <= request!.input!.maxBytes);
  }
  assert.ok(pages.some((page) => page.nextCursor !== undefined));
  const submissions = trace.filter(
    (event) =>
      event.event === "request" &&
      event.tool === "record_codex_security_deep_reduction",
  );
  const submissionIds = new Set(submissions.map((event) => event.id));
  const recorded = trace.filter(
    (event) => event.event === "response" && submissionIds.has(event.id),
  );
  assert.equal(
    recorded.length,
    1,
    "the reducer must successfully record its result exactly once",
  );
  const pageEdges = new Map<string | undefined, Set<string | undefined>>();
  for (const page of trace) {
    if (page.event === "request" && page.id === recorded[0].id) break;
    const request = readsById.get(page.id);
    if (
      page.event !== "response" ||
      page.injected ||
      !request ||
      request.input!.findingRef !== undefined
    )
      continue;
    const cursor = request.input!.cursor ?? "0";
    const edges = pageEdges.get(cursor) ?? new Set();
    edges.add(page.nextCursor);
    pageEdges.set(cursor, edges);
  }
  const reached = new Set<string | undefined>(["0"]);
  for (const cursor of reached) {
    for (const next of pageEdges.get(cursor) ?? []) {
      reached.add(next);
    }
  }
  assert.equal(
    reached.has(undefined),
    true,
    "read every assigned-input page before recording",
  );
  return {
    actualOversizedResponseBytes: injected[0].bytes!,
    firstBudget: failed!.input!.maxBytes,
    recoveryBudget: retried.input!.maxBytes,
    successfulPages: pages.length,
    assignedInputsFullyRead: reached.has(undefined),
    referenceReads: reads.filter((event) => event.input!.findingRef).length,
  };
}

// The controlled provider drives the real tools. It does not simulate their
// results, the frame limit, or recording. The model mode uses only the shipped
// reducer prompt and must discover and carry out recovery itself.
const controlledReducerCode = `// @exec: {"yield_time_ms": 60000}
let maxBytes = 1024 * 1024;
async function readDocument(findingRef) {
  let cursor;
  const fragments = [];
  do {
    const input = {maxBytes, ...(cursor === undefined ? {} : {cursor}),
      ...(findingRef === undefined ? {} : {findingRef})};
    let response;
    try {
      response = await tools.mcp__cs_artifacts__get_codex_security_deep_reducer_inputs(input);
    } catch (error) {
      text(String(error));
      maxBytes = Math.floor(maxBytes / 2);
      response = await tools.mcp__cs_artifacts__get_codex_security_deep_reducer_inputs({...input, maxBytes});
    }
    if (response.isError) throw new Error(response.content[0].text);
    const page = JSON.parse(response.content[0].text);
    fragments.push(page.json);
    cursor = page.nextCursor;
  } while (cursor !== undefined);
  return JSON.parse(fragments.join(''));
}
const inputs = await readDocument();
const original = await readDocument('source:' + inputs.previous.findings[0].provenance.sourceFindingIds[0]);
const prior = await readDocument('previous:0');
if (original.identity.anchor !== prior.identity.anchor) throw new Error('Wrong reference resolved');
const findings = [...inputs.discoveries.flatMap(entry => entry.result.findings), ...inputs.previous.findings];
for (const finding of findings) {
  // The large summary explicitly marks repeated transport padding, not evidence.
  if (finding.summary.startsWith('BEGIN ISSUE:')) {
    finding.summary = finding.summary.split('\\n', 1)[0] + '\\n' + finding.summary.slice(finding.summary.lastIndexOf('END ISSUE:'));
  }
}
const result = await tools.mcp__cs_artifacts__record_codex_security_deep_reduction({
  scanId: inputs.previous.scanId, findings
});
if (result.isError) throw new Error(result.content[0].text);
text({reductionRecorded: true});
`;

import { readJson } from "../json.ts";
import type { TextContent } from "@modelcontextprotocol/sdk/types.js";
import type { ZodRawShapeCompat } from "@modelcontextprotocol/sdk/server/zod-compat.js";
import { appendFile } from "node:fs/promises";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { getCodexSecurityDeepReducerInputs } from "../../../src/artifact-deep-reducer.js";
import { registerCompactWorkerArtifactTools } from "../../../src/server/compact-artifact-tools.js";

async function main() {
  const { context, tracePath } = await readJson(process.argv[2]);
  const server = new McpServer({
    name: "deep-reducer-paging-eval",
    version: "1",
  });
  type RegisterTool = typeof server.registerTool<
    ZodRawShapeCompat,
    ZodRawShapeCompat
  >;
  let injected = false;
  let sequence = 0;

  // Exercise the production tool registration and handlers. Only the first read
  // returns the old duplicated result, forcing a real code-mode transport error.
  registerCompactWorkerArtifactTools(
    {
      registerTool(...[name, definition, handler]: Parameters<RegisterTool>) {
        return server.registerTool(name, definition, async (input, extra) => {
          const id = ++sequence;
          const read = name === "get_codex_security_deep_reducer_inputs";
          await trace({
            event: "request",
            id,
            tool: name,
            ...(read
              ? { input }
              : {
                  findingCount: (input.findings as unknown[] | undefined)
                    ?.length,
                }),
          });
          try {
            let result;
            const inject = read && !injected;
            if (inject) {
              injected = true;
              const full = await getCodexSecurityDeepReducerInputs(context);
              result = {
                content: [
                  { type: "text" as const, text: JSON.stringify(full) },
                ],
                structuredContent: full as unknown as Record<string, unknown>,
              };
            } else {
              result = await handler(input, extra);
            }
            await trace({
              event: "response",
              id,
              injected: inject,
              bytes: Buffer.byteLength(JSON.stringify(result)),
              ...(read && !inject
                ? {
                    nextCursor: JSON.parse(
                      (result.content[0] as TextContent).text,
                    ).nextCursor,
                  }
                : {}),
            });
            return result;
          } catch (error) {
            await trace({
              event: "error",
              id,
              message: (error as Error).message,
            });
            throw error;
          }
        });
      },
    } as unknown as McpServer,
    context,
  );

  await server.connect(new StdioServerTransport());

  async function trace(event: Record<string, unknown>) {
    await appendFile(tracePath, JSON.stringify(event) + "\n");
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

